var i=[{title:`Миттєва високопотужна енергія`,text:`Система АТФ-креатинфосфат (фосфагенна) може швидко поповнювати АТФ під час коротких високопотужних зусиль, як-от стрибок, старт спринту чи важкий підхід. Вона може підтримувати максимальну віддачу лише недовго, що допомагає пояснити, чому кілька хвилин відпочинку можуть відновити результат між важкими силовими чи швидкісними зусиллями.`},{title:`Швидке розщеплення вуглеводів`,text:`Анаеробний гліколіз постачає АТФ із вуглеводів, а реакції, що його виробляють, не потребують кисню. Він найважливіший під час важких зусиль, що тривають від багатьох секунд до кількох хвилин. Лактат часто називають «відходами» чи звинувачують як єдину причину болючості, але тіло також використовує його як паливо та метаболічний сигнал.`},{title:`Тривале аеробне вироблення`,text:`Окисний метаболізм у мітохондріях використовує кисень, щоб робити АТФ з вуглеводів і жирів. Він забезпечує довгі прогулянки, їзду на велосипеді, рівний біг і значну частину відновлення між важкими інтервалами. Навіть короткі зусилля отримують частку аеробного внеску, адже системи ніколи не вмикаються й вимикаються в окремих часових рамках.`},{title:`Чому важливі тривалість і відпочинок`,text:`Майже максимальний п’ятисекундний спринт і 30-хвилинна прогулянка потребують дуже різної потужності. Повторювані 20-секундні важкі інтервали з коротким відпочинком ускладнюють підтримання віддачі, коли наростає втома. Важкі підходи зі штангою зазвичай потребують довшого відпочинку, щоб зберегти силу й техніку, а мета не в тому, щоб задихатися якомога сильніше.`},{title:`Застосування на практиці`,text:`Давайте собі достатньо відновлення, коли головна ціль є сила чи швидкість. Використовуйте рівну помірну активність, щоб розвивати аеробну здатність. Застосовуйте інтервали для витривалості, коли вони підходять, і підбирайте роботу та відпочинок за поточними можливостями. Високий пульс під час підйомів не означає, що заняття дало такий самий аеробний стимул, як тривале кардіо.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Настанови ВООЗ щодо аеробної активності`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var s={sections:i,sources:l};export{s as default,i as sections,l as sources};